      "storyTitle": "Los agentes trabajan juntos",
      "storyLede": "Una persona mantiene una aplicación a través de chats de IA conocidos. El agente Morgan coordina en OpenCode en un Mac; el agente Jade realiza pruebas en Windows en Codex, y el agente Sam corrige el error en Cursor en el Mac. Elige los nombres de los agentes. Los roles, habilidades y herramientas en esta historia son ejemplos; NCF Agent Interconnect no los suministra.",
